describe('Tab Navigation with URL Hash', () => {
  beforeEach(() => {
    cy.visit('http://localhost:3000');
  });

  it('should update URL hash when clicking on a tab', () => {
    cy.get('[data-testid="tab-panel"]').should('exist');
    cy.get('[data-testid="tab-button"][data-tab="tab1"]').click();
    cy.url().should('include', '#tab1');
    cy.get('[data-testid="tab-content-tab1"]').should('be.visible');
  });

  it('should display correct tab content when hash is in URL on page load', () => {
    cy.visit('http://localhost:3000#tab2');
    cy.get('[data-testid="tab-content-tab2"]').should('be.visible');
    cy.get('[data-testid="tab-button"][data-tab="tab2"]').should('have.class', 'active');
  });

  it('should switch between multiple tabs and update hash accordingly', () => {
    cy.get('[data-testid="tab-button"][data-tab="tab1"]').click();
    cy.url().should('include', '#tab1');
    cy.get('[data-testid="tab-content-tab1"]').should('be.visible');

    cy.get('[data-testid="tab-button"][data-tab="tab3"]').click();
    cy.url().should('include', '#tab3');
    cy.get('[data-testid="tab-content-tab3"]').should('be.visible');
    cy.get('[data-testid="tab-content-tab1"]').should('not.be.visible');
  });

  it('should handle invalid hash gracefully and show default tab', () => {
    cy.visit('http://localhost:3000#invalid-tab');
    cy.get('[data-testid="tab-content-tab1"]').should('be.visible');
    cy.url().should('include', '#invalid-tab');
  });

  it('should update hash when using browser back button', () => {
    cy.get('[data-testid="tab-button"][data-tab="tab1"]').click();
    cy.url().should('include', '#tab1');

    cy.get('[data-testid="tab-button"][data-tab="tab2"]').click();
    cy.url().should('include', '#tab2');

    cy.go('back');
    cy.url().should('include', '#tab1');
    cy.get('[data-testid="tab-content-tab1"]').should('be.visible');
  });

  it('should maintain tab state when navigating away and returning', () => {
    cy.get('[data-testid="tab-button"][data-tab="tab2"]').click();
    cy.url().should('include', '#tab2');

    cy.visit('http://localhost:3000/other-page');
    cy.visit('http://localhost:3000#tab2');
    cy.get('[data-testid="tab-content-tab2"]').should('be.visible');
  });

  it('should handle rapid tab clicks without losing hash state', () => {
    cy.get('[data-testid="tab-button"][data-tab="tab1"]').click();
    cy.get('[data-testid="tab-button"][data-tab="tab2"]').click();
    cy.get('[data-testid="tab-button"][data-tab="tab3"]').click();
    cy.url().should('include', '#tab3');
    cy.get('[data-testid="tab-content-tab3"]').should('be.visible');
  });

  it('should preserve hash when page is refreshed', () => {
    cy.get('[data-testid="tab-button"][data-tab="tab2"]').click();
    cy.url().should('include', '#tab2');

    cy.reload();
    cy.url().should('include', '#tab2');
    cy.get('[data-testid="tab-content-tab2"]').should('be.visible');
  });
});
